const feed1 = $('RSS: TechCrunch AI').all().map(i => i.json);

const combined = feed1
  .filter(item => item.title)
  .sort((a, b) => new Date(b.isoDate || b.pubDate || 0) - new Date(a.isoDate || a.pubDate || 0))
  .slice(0, 10)
  .map(item => `- "${item.title}"`)
  .join('\n');

return [
  {
    json: {
      rssHeadlines: combined || '(no recent items fetched)'
    }
  }
];

const recentPosts = $('Get recent posts').all().map(item => item.json);
const internalCandidates = $('Get internal link candidates').all().map(item => item.json);
const ideaRow = $('Get queued topic idea').first().json;
const hasIdea = ideaRow.has_idea === true;

let rss = '(skipped -- a queued idea took priority this run)';

if (!hasIdea) {
  try {
    rss = $('Merge RSS items').first().json.rssHeadlines;
  } catch (e) {
    rss = '(no recent items fetched)';
  }
}

const usedTopics = recentPosts
  .map(p => `- "${p.title}" (keyword: ${p.keyword}${p.source_topic ? `, angle: ${p.source_topic}` : ''})`)
  .join('\n') || '(none yet)';

const internalLinkList = internalCandidates
  .map(p => `- /blog/${p.slug} -- "${p.title}"`)
  .concat([
    "- /services -- Noctix's full services overview page",
    '- /case-studies -- Noctix client case studies',
    '- /contact -- Book an automation audit',
  ])
  .join('\n');

const servicePillars = [
  'AI Voice Agents (inbound Voxie, outbound Voxo)',
  'CRM & Workflow Automation',
  'Lead Generation Systems',
  'Marketing Automation',
  'Dashboards & Reporting',
  'Custom AI Tools',
  'API Integrations',
].join(', ');

const styleReference = `Most CRMs are clean for about three weeks. After that, fields go missing, leads get stuck in the wrong stage, and the pipeline stops reflecting reality. CRM automation is what keeps it usable.

The goal isn't to automate everything -- it's to remove the manual steps that always get skipped when the team is busy.`;

const systemPrompt = `You are a senior operations writer for Noctix AI, an AI automation agency that builds voice agents, CRM automations, workflow automations, lead generation systems, marketing automation, and dashboards for businesses in the US, UK, and Pakistan.

You write like an operator who has actually built these systems -- direct, concrete, no filler, no hype words like "revolutionize" or "game-changing" or "unlock". Short paragraphs. Real specifics over vague claims. This is the voice of an existing post on the site, match this tone exactly:

"""
${styleReference}
"""

You are writing ONE new blog post. Output ONLY valid JSON matching the schema below -- no markdown code fences, no commentary before or after, just the JSON object.`;

const topicGuidance = hasIdea
  ? `A human has specifically suggested this topic idea -- prioritize writing about this unless it's a near-duplicate of something already covered above: "${ideaRow.idea}" (source: ${ideaRow.source || 'manual'})`
  : `No specific human-suggested topic is queued this time. Choose the best topic using the signals below, in this priority order:
1. Recent AI industry news below -- only if something genuinely connects to a Noctix service and is worth a timely angle.
2. Noctix's service pillars generally, filling a gap not yet covered.

Recent AI industry headlines (use only if genuinely relevant to a Noctix service -- do not force a connection that isn't there):
${rss}`;

const userPrompt = `Noctix's core service pillars: ${servicePillars}

${topicGuidance}

Topics already covered on the blog -- do NOT repeat these or pick a near-duplicate angle:
${usedTopics}

Real internal pages you may link to (pick 2-4 of these, and ONLY these -- never invent a URL):
${internalLinkList}

Task:
1. Pick ONE specific, narrow topic related to Noctix's services that is NOT already covered above, following the topic guidance given.
2. Write a full blog post about it, 1000-1600 words, following this structure:
   - The first 1-2 sentences must directly answer the core question a reader has, in plain language, before any setup or context. AI search engines (ChatGPT, Perplexity, Google AI Overviews) extract answers from roughly the first 500 words, so the direct answer cannot be buried.
   - 4-7 H2 sections (use "## " markdown), each covering one concrete sub-point.
   - Natural paragraph prose, not bullet-point-only content. Short paragraphs (2-4 sentences).
   - A natural closing paragraph connecting the topic back to what Noctix builds, without being a hard sales pitch mid-article -- one clear mention of Noctix is enough.
   - 3-5 FAQ question/answer pairs covering related questions a reader would still have (each answer 1-3 sentences).
3. Propose 2-3 external links to genuinely well-known, authoritative sources (official documentation, established research or news organizations, well-known tool vendors) that support a specific factual claim you make in the post. Never link to a company that competes directly with Noctix's automation-agency services. If you are not confident of the exact real URL for a source, use the organization's known root domain plus your best-effort path -- a validation step will check these before publishing, so do not fabricate a specific statistic or quote to justify a link; only propose a link where the general claim is true regardless of the exact page.

Output this exact JSON shape:
{
  "title": "string, compelling, under 65 characters",
  "meta_title": "string, keyword near the front, under 60 characters",
  "meta_description": "string, 140-160 characters, includes the target keyword",
  "slug": "string, lowercase-hyphenated, under 60 characters",
  "keyword": "string, the primary target keyword/phrase",
  "secondary_keywords": ["string", "string"],
  "description": "string, 1-2 sentence teaser for the blog index card",
  "body": "string, the full post in markdown using ## for H2 headers, with internal links written as [anchor text](/blog/slug-here) and external links written as [anchor text](https://example.com/path) inline in the prose where relevant",
  "faq": [{"question": "string", "answer": "string"}],
  "internal_links": [{"slug": "string, matching one of the real pages listed above exactly", "anchor_text": "string"}],
  "external_links": [{"url": "string", "anchor_text": "string", "reason": "string, one sentence on why this source"}],
  "source_topic": "string, one sentence explaining why you picked this angle -- state explicitly whether it came from the human-suggested idea, AI news, or general reasoning",
  "read_time_minutes": integer
}`;

return [{
  json: {
    systemPrompt,
    userPrompt,
    queuedIdeaId: hasIdea ? ideaRow.id : null,
  }
}];

const raw = $input.first().json;
const content = raw.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('OpenRouter response had no message content -- check the model ID and API key. Raw response: ' + JSON.stringify(raw).slice(0, 500));
}

let cleaned = content.trim();
cleaned = cleaned.replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/```\s*$/, '');

let post;
try {
  post = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Model did not return valid JSON. First 500 chars: ' + cleaned.slice(0, 500));
}

const required = ['title', 'meta_title', 'meta_description', 'slug', 'keyword', 'description', 'body', 'faq', 'internal_links', 'external_links', 'source_topic'];
for (const field of required) {
  if (post[field] === undefined) {
    throw new Error(`Model output is missing required field: ${field}`);
  }
}

post.slug = String(post.slug)
  .toLowerCase()
  .trim()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');

if (!post.slug) {
  throw new Error('Generated slug was empty after normalization');
}

const minutes = post.read_time_minutes || Math.max(1, Math.round((post.body.split(/\s+/).length) / 200));
post.read_time = `${minutes} min read`;

// n8n's Code node sandbox disallows require('crypto'), so this generates
// the approval token with plain JS instead -- no module needed, works
// regardless of instance security settings.
function randomHex(length) {
  const chars = '0123456789abcdef';
  let out = '';
  for (let i = 0; i < length; i++) {
    out += chars[Math.floor(Math.random() * chars.length)];
  }
  return out;
}
post.approval_token = randomHex(48);

post.queued_idea_id = $('Build generation prompt').first().json.queuedIdeaId;

return [{ json: post }];

// Code node: "Build insert SQL"
// Mode: Run Once for All Items (this workflow processes one post per run)
//
// This node's own immediate input is "Validate external links", which only
// carries { valid_links, rejected_links, slack_message } -- not the post
// itself. The generated post is read from "Parse and validate LLM output"
// directly via node reference, and the *validated* external links (not the
// model's raw, unvalidated proposal) are read from "Validate external
// links".
//
// Fixes vs. the previous version of this node:
//   1. Internal links: normalizes each l.slug instead of blindly
//      prepending '/blog/', which produced /blog//blog/some-slug whenever
//      the model already returned a pre-formatted target (it usually does
//      -- see the internal-link candidate list built in "Build generation
//      prompt", which already lists paths as "/blog/actual-slug").
//   2. SQL: emits { query, values } with $1, $2, ... placeholders instead of
//      building the statement with manual ".replace(/'/g, "''")" escaping.
//      Adds ON CONFLICT (slug) DO NOTHING + RETURNING, and word_count.
//
// Downstream wiring this requires:
//   - "Insert draft" (Postgres, Execute Query): Query = {{ $json.query }},
//     Query Parameters/Query Replacement = {{ $json.values }}, and
//     "Always Output Data" ON (ON CONFLICT DO NOTHING returns zero rows on
//     a duplicate slug -- without this the branch just stops).
//   - The "Insert succeeded?" IF node after it branches on {{$json.slug}}.

const post = $('Parse and validate LLM output').first().json;
const validated = $('Validate external links').first().json;

function normalizeInternalLink(rawSlug) {
  if (typeof rawSlug !== 'string' || !rawSlug.trim()) return null;

  const path = rawSlug.trim().replace(/^\/+/, ''); // strip leading slashes

  let normalized;
  if (path.startsWith('blog/')) {
    normalized = '/blog/' + path.slice('blog/'.length);
  } else if (
    path.startsWith('services') ||
    path.startsWith('contact') ||
    path.startsWith('case-studies')
  ) {
    normalized = '/' + path;
  } else {
    // No recognized prefix -- treat the whole value as a bare blog slug.
    normalized = '/blog/' + path;
  }

  normalized = normalized.replace(/\/{2,}/g, '/'); // collapse repeated slashes

  return /^\/[a-z0-9\-\/]+$/.test(normalized) ? normalized : null;
}

const internalLinks = (Array.isArray(post.internal_links) ? post.internal_links : [])
  .map((l) => {
    const url = normalizeInternalLink(l && l.slug);
    return url ? { url, anchor_text: l && l.anchor_text } : null;
  })
  .filter(Boolean);

// Store what actually passed validation, not the model's raw proposal.
const externalLinks = (validated.valid_links || []).map((l) => ({
  url: l.url,
  anchor_text: l.anchor_text,
}));

const bodyText = typeof post.body === 'string' ? post.body.trim() : '';
const wordCount = bodyText ? bodyText.split(/\s+/).filter(Boolean).length : 0;

const COLUMNS = [
  'slug',
  'title',
  'meta_title',
  'meta_description',
  'description',
  'keyword',
  'secondary_keywords',
  'body',
  'faq',
  'internal_links',
  'external_links',
  'author_name',
  'read_time',
  'status',
  'approval_token',
  'source_topic',
  'word_count',
];

const COLUMN_CASTS = {
  secondary_keywords: 'text[]',
  faq: 'jsonb',
  internal_links: 'jsonb',
  external_links: 'jsonb',
};

const row = {
  slug: post.slug,
  title: post.title,
  meta_title: post.meta_title,
  meta_description: post.meta_description,
  description: post.description,
  keyword: post.keyword,
  secondary_keywords: Array.isArray(post.secondary_keywords) ? post.secondary_keywords : [],
  body: post.body,
  faq: JSON.stringify(post.faq ?? []),
  internal_links: JSON.stringify(internalLinks),
  external_links: JSON.stringify(externalLinks),
  author_name: 'Ayaan Awan',
  read_time: post.read_time,
  status: 'draft',
  approval_token: post.approval_token,
  source_topic: post.source_topic,
  word_count: wordCount,
};

const values = COLUMNS.map((col) => row[col]);
const placeholders = COLUMNS.map((col, i) => {
  const cast = COLUMN_CASTS[col];
  return cast ? `$${i + 1}::${cast}` : `$${i + 1}`;
}).join(', ');

const query = `
INSERT INTO blog_posts
  (${COLUMNS.join(', ')})
VALUES (${placeholders})
ON CONFLICT (slug) DO NOTHING
RETURNING id, slug, approval_token
`;

return [
  {
    json: {
      query,
      values,
      queued_idea_id: post.queued_idea_id,
      internal_links_normalized: internalLinks,
    },
  },
];

const built = $('Build insert SQL').first().json;
const id = built.queued_idea_id;

const sql = id
  ? `UPDATE blog_topic_ideas SET status='used', used_at=now() WHERE id='${String(id).replace(/'/g, "''")}' AND status='queued';`
  : `SELECT 1;`;

return [{ json: { sql } }];

// Code node: "Build Slack message"
//
// Reads the post from "Parse and validate LLM output" (its own immediate
// input, "Mark idea used if applicable", only carries idea-table SQL
// bookkeeping, not the post). Reads the validated external links section
// pre-built by "Validate external links" instead of re-deriving it, and
// the normalized internal links from "Build insert SQL" so the slugs shown
// here match exactly what got stored on the row.

const post = $('Parse and validate LLM output').first().json;
const validated = $('Validate external links').first().json;
const built = $('Build insert SQL').first().json;
const inserted = $('Insert draft').first().json;

const baseUrl = 'https://noctix.app';
const approveUrl = `https://n8nautomations.noctix.app/webhook/noctix-blog-approve?post=${inserted.id}&token=${inserted.approval_token}&action=approve`;
const rejectUrl = `https://n8nautomations.noctix.app/webhook/noctix-blog-approve?post=${inserted.id}&token=${inserted.approval_token}&action=reject`;
const previewUrl = `${baseUrl}/blog/preview/${inserted.slug}?token=${inserted.approval_token}`;

const internalLines =
  (built.internal_links_normalized || [])
    .map((l) => `\u2022 <${baseUrl}${l.url}|${l.anchor_text}>`)
    .join('\n') || '_none_';

const text =
  `\uD83D\uDCDD *New blog draft ready for review*\n\n` +
  `*${post.title}*\n` +
  `_Keyword: ${post.keyword}_\n\n` +
  `${post.description}\n\n` +
  `*Why this topic:* ${post.source_topic}\n\n` +
  `*Internal links:*\n${internalLines}\n\n` +
  `${validated.slack_message}\n\n` +
  `<${previewUrl}|\uD83D\uDCC4 Preview the full post>\n\n` +
  `<${approveUrl}|\u2705 Approve & publish>   \u00b7   <${rejectUrl}|\u274C Reject>`;

return [{ json: { slack_message: text } }];

// Code node: "Validate external links" (aggregate)
// Mode: Run Once for All Items
//
// Reads the per-link HTTP responses from this node's own input, and pulls the
// original link (url + anchor_text) back from the Split Out node via
// itemMatching() so the two stay correctly paired regardless of item order.
//
// IMPORTANT: leave "Continue On Fail" OFF on *this* node. The throw below is
// what's supposed to stop the workflow and hand off to the configured Error
// Workflow. Swallowing it here would let a post with zero citations publish
// anyway — which is the exact failure mode this fix closes.

const SPLIT_OUT_NODE = 'Split Out External Links';
const MAX_VALID_LINKS = 3;

const items = $input.all();
const valid = [];
const rejected = [];

for (let i = 0; i < items.length; i++) {
  const response = items[i].json;
  const sourceLink = $(SPLIT_OUT_NODE).itemMatching(i).json.link;

  const url = sourceLink && typeof sourceLink === 'object' ? sourceLink.url : sourceLink;
  const anchorText =
    sourceLink && typeof sourceLink === 'object' ? sourceLink.anchor_text : undefined;

  // With "Never Error" on, every completed request lands here with a numeric
  // statusCode — success or not. Only hard failures (DNS, connection refused,
  // the 8s timeout) skip that and show up as an item-level error instead.
  if (response.error || typeof response.statusCode !== 'number') {
    rejected.push({
      url,
      status: null,
      reason: response.error?.message ?? String(response.error ?? 'request failed'),
    });
    continue;
  }

  const status = response.statusCode;

  if (status < 400) {
    if (valid.length < MAX_VALID_LINKS) {
      valid.push({ url, anchor_text: anchorText, status });
    }
    // Extra passing links beyond the cap are just not carried forward — the
    // target site didn't reject them, so they don't belong in rejected_links
    // either. They're simply unused.
  } else {
    rejected.push({ url, status, reason: `HTTP ${status}` });
  }
}

if (valid.length === 0) {
  throw new Error(
    `External link validation: 0 of ${items.length} candidate link(s) passed. ` +
      rejected.map((r) => `${r.url} -> ${r.status ?? r.reason}`).join('; '),
  );
}

const slackLines = [
  `*External links (${valid.length}/${MAX_VALID_LINKS} used):*`,
  ...(valid.length
    ? valid.map((l) => `• <${l.url}|${l.anchor_text || l.url}> — HTTP ${l.status}`)
    : ['_none validated_']),
];

if (rejected.length) {
  slackLines.push('', `*Rejected (${rejected.length}):*`);
  slackLines.push(
    ...rejected.map((l) => `• ${l.url} — ${l.status ? `HTTP ${l.status}` : l.reason}`),
  );
}

return [
  {
    json: {
      valid_links: valid,
      rejected_links: rejected,
      slack_message: slackLines.join('\n'),
    },
  },
];
